import fs from 'node:fs/promises';

const stamp = value => {
  const n = Date.parse(value || '');
  return Number.isFinite(n) ? n : null;
};

// Never replace a newer independent supplier audit or newer owner board with
// a cached cloud-growth snapshot generated by a concurrent workflow.
export function boardPublicationDecision(snapshot, mainReview, mainBoard) {
  const generated = stamp(snapshot?.generatedAt);
  if (generated === null || !Array.isArray(snapshot?.tasks)) return {publish:false,reason:'invalid_snapshot'};
  const snapshotCJ = stamp(snapshot?.verifiedCJStatus?.checkedAt);
  const latestCJ = stamp(mainReview?.checkedAt);
  if (latestCJ !== null && (snapshotCJ === null || snapshotCJ < latestCJ)) {
    return {publish:false,reason:'newer_supplier_review_on_main'};
  }
  const published = stamp(mainBoard?.generatedAt);
  if (published !== null && generated < published) return {publish:false,reason:'newer_worker_board_on_main'};
  return {publish:true,reason:'snapshot_current'};
}

async function run(args) {
  if (args.length !== 3) throw new Error('Three paths required: snapshot, main review, main board');
  const read = async p => {
    try { return JSON.parse(await fs.readFile(p,'utf8')); }
    catch (err) { if (err.code === 'ENOENT') return null; throw err; }
  };
  const [snapshot, review, board] = await Promise.all(args.map(read));
  const result = boardPublicationDecision(snapshot,review,board);
  console.log(JSON.stringify(result));
  process.exitCode = result.publish ? 0 : 10;
}

if (process.argv[1] && import.meta.url === new URL('file://' + process.argv[1].replaceAll('\\','/')).href) {
  run(process.argv.slice(2)).catch(() => {console.error('board_comparison_failed');process.exitCode=11;});
}
